import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.bGC-1KKp.js";const g=JSON.parse('{"title":"Mandat — Aventure Saint-Maurice","description":"","frontmatter":{"title":"Mandat — Aventure Saint-Maurice","aside":false},"headers":[],"relativePath":"mandat/index.md","filePath":"mandat/index.md"}'),i={name:"mandat/index.md"};function s(l,e,o,u,d,c){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="mandat-—-aventure-saint-maurice" tabindex="-1">Mandat — Aventure Saint-Maurice <a class="header-anchor" href="#mandat-—-aventure-saint-maurice" aria-label="Permalink to &quot;Mandat — Aventure Saint-Maurice&quot;">​</a></h1><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Le fil conducteur de la session</strong><br> Toutes les activités, les laboratoires et les évaluations 1, 2 et 3 portent sur ce mandat. Votre équipe joue le rôle d&#39;une petite agence Web, <strong>Studio Web FC</strong>, qui vient d&#39;être approchée par un nouveau client. Gardez cette page sous la main : vous y reviendrez souvent. </div><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Une entreprise fictive</strong><br> Aventure Saint-Maurice n&#39;existe pas. Toute ressemblance avec une entreprise réelle de la Mauricie serait une coïncidence. Les outils et les services nommés par le client, eux, existent vraiment. </div><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Pour surligner et annoter</strong><br> Téléchargez les trois documents du mandat et placez-les dans le dossier partagé de votre équipe : <ul class="list-disc pl-5"><li><a href="./../fiches/mandat-aventure-saint-maurice.docx" download>Mandat — version Word</a> (outil <em>Couleur de surbrillance</em> de l&#39;onglet Accueil)</li><li><a href="./../fiches/mandat-aventure-saint-maurice.pdf" download>Mandat — version PDF</a> (outil <em>Surligner</em> d&#39;Edge ou d&#39;Acrobat, ou pour imprimer)</li></ul></div><h2 id="le-client-en-bref" tabindex="-1">Le client en bref <a class="header-anchor" href="#le-client-en-bref" aria-label="Permalink to &quot;Le client en bref&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Entreprise</strong></td><td style="text-align:left;">Aventure Saint-Maurice inc. — centre de plein air sur la rivière Saint-Maurice, à environ 45 minutes au nord de Trois-Rivières</td></tr><tr><td style="text-align:left;"><strong>Depuis</strong></td><td style="text-align:left;">2014</td></tr><tr><td style="text-align:left;"><strong>Propriétaires</strong></td><td style="text-align:left;">Mélanie Gauthier (gestion, administration, marketing) et Patrick Lavoie (guide en chef, équipement, sécurité)</td></tr><tr><td style="text-align:left;"><strong>Activités</strong></td><td style="text-align:left;">Location de kayaks, excursions guidées en kayak et en rabaska, via ferrata, six tentes prêt-à-camper</td></tr><tr><td style="text-align:left;"><strong>Saison</strong></td><td style="text-align:left;">Du 1<sup>er</sup> juin à la fête du Travail, puis les fins de semaine jusqu&#39;à l&#39;Action de grâce</td></tr><tr><td style="text-align:left;"><strong>Personnel</strong></td><td style="text-align:left;">Les deux propriétaires à l&#39;année, une employée à l&#39;accueil l&#39;été, de 12 à 15 guides saisonniers (surtout des étudiants)</td></tr><tr><td style="text-align:left;"><strong>Site actuel</strong></td><td style="text-align:left;"><code>aventure-stmaurice.com</code>, fait sur Wix en 2017</td></tr></tbody></table><hr><h2 id="document-1-—-le-courriel-du-client" tabindex="-1">Document 1 — Le courriel du client <a class="header-anchor" href="#document-1-—-le-courriel-du-client" aria-label="Permalink to &quot;Document 1 — Le courriel du client&quot;">​</a></h2><div class="courriel"><div class="courriel-entete"><div><span>De :</span> Mélanie Gauthier &lt;melanie@aventure-stmaurice.com&gt;</div><div><span>À :</span> info@studiowebfc.ca</div><div><span>Date :</span> 16 septembre 2026, 22 h 47</div><div><span>Objet :</span> Nouveau site Web (on n&#39;en peut plus du téléphone!)</div></div><div class="courriel-corps"><p>Bonjour,</p><p>C&#39;est Tourisme Mauricie qui m&#39;a donné votre nom. Je vais être franche : on a besoin d&#39;aide et on ne connaît rien là-dedans.</p><p>Aventure Saint-Maurice, c&#39;est un centre de plein air qu&#39;on a fondé en 2014, mon conjoint Patrick et moi. Kayak, rabaska, via ferrata et un peu de camping. Ça va bien, trop bien même : l&#39;été passé, on a eu environ 9 000 clients et je pense que j&#39;ai passé la moitié de mon été au téléphone.</p><p>En ce moment, les gens nous appellent, nous écrivent sur Messenger ou par courriel, et je note tout dans un fichier Excel partagé avec l&#39;accueil. Il y a des erreurs tout le temps. Deux fois cet été, on a vendu les mêmes kayaks à deux groupes différents. Et les groupes qui réservent 30 places et qui arrivent à 18, ça nous coûte cher.</p><p>Notre site a été fait par le neveu de Patrick quand il était au cégep. Il est beau, mais les prix affichés datent de 2022 et personne ici ne sait comment le modifier. Le neveu habite maintenant à Vancouver.</p><p>Ce qu&#39;on voudrait :</p><ul><li>que les gens puissent <strong>réserver et payer en ligne</strong>, avec les heures de départ et les places qui restent ;</li><li>que la <strong>décharge de responsabilité</strong> se signe avant d&#39;arriver (en ce moment, c&#39;est du papier, et le samedi matin il y a une file de 40 personnes devant le comptoir) ;</li><li>vendre des <strong>cartes-cadeaux</strong>, surtout pour Noël ;</li><li>un site en <strong>français et en anglais</strong>, parce qu&#39;on a beaucoup d&#39;Ontariens et d&#39;Américains ;</li><li>mettre en valeur les <strong>vidéos de drone</strong> de Patrick, elles sont vraiment belles ;</li><li>quelque chose de <strong>simple</strong>, qu&#39;on peut modifier nous-mêmes. Pas de flafla.</li></ul><p>Le plus important : on ouvre les réservations d&#39;été le <strong>1<sup>er</sup> mars</strong>. C&#39;est là que tout se joue. Il faudrait que le nouveau site soit prêt pour ça.</p><p>Pour le budget, on pensait à environ <strong>8 000 $</strong>. On a fait une demande de subvention à la MRC, mais on n&#39;a pas encore la réponse.</p><p>Est-ce que c&#39;est faisable? On serait disponibles pour une rencontre la semaine prochaine, n&#39;importe quel soir sauf le jeudi.</p><p>Merci et bonne soirée,</p><p>Mélanie Gauthier<br> Copropriétaire — Aventure Saint-Maurice<br> 819 555-0142</p></div></div><hr><h2 id="document-2-—-les-notes-de-la-premiere-rencontre" tabindex="-1">Document 2 — Les notes de la première rencontre <a class="header-anchor" href="#document-2-—-les-notes-de-la-premiere-rencontre" aria-label="Permalink to &quot;Document 2 — Les notes de la première rencontre&quot;">​</a></h2><div class="notes-rencontre"><p><strong>Rencontre de découverte — Aventure Saint-Maurice</strong><br><strong>Date :</strong> 22 septembre 2026, 19 h, au chalet d&#39;accueil du centre<br><strong>Présents :</strong> Mélanie Gauthier, Patrick Lavoie, Karine Bélanger (responsable de l&#39;accueil l&#39;été), le chargé de projet de Studio Web FC<br><strong>Notes prises par :</strong> le chargé de projet</p><h3 id="les-activites-et-les-reservations" tabindex="-1">Les activités et les réservations <a class="header-anchor" href="#les-activites-et-les-reservations" aria-label="Permalink to &quot;Les activités et les réservations&quot;">​</a></h3><ul><li>Quatre produits : <strong>location de kayak</strong> (à l&#39;heure ou à la journée), <strong>excursions guidées</strong> (kayak ou rabaska, départs à heures fixes), <strong>via ferrata</strong> (deux parcours, départs aux 30 minutes, 8 personnes maximum par départ), <strong>prêt-à-camper</strong> (6 tentes, à la nuit).</li><li>Les groupes (écoles, camps de jour, entreprises) représentent environ <strong>35 % des revenus</strong>. Ils demandent presque toujours une <strong>soumission</strong> et paient un <strong>dépôt de 30 %</strong> par virement Interac. Mélanie envoie les factures à la main dans Word.</li><li>Depuis 2025, l&#39;entreprise est aussi sur <strong>Viator</strong> (plateforme de réservation pour touristes). Viator prend une commission de 25 %. « Ça marche bien avec les Américains. » Les réservations Viator arrivent par courriel et Karine les recopie dans l&#39;Excel. C&#39;est là que les doubles réservations sont arrivées.</li><li>Paiement sur place avec un terminal <strong>Square</strong>. « On aime bien Square, on voudrait le garder. »</li><li>Patrick : « Quand il y a un orage, on annule tous les départs. Karine doit appeler chaque client un par un. Des fois, ça fait 60 appels dans l&#39;après-midi. »</li><li>Politique d&#39;annulation actuelle : aucune. « On rembourse quand les gens chialent. » Mélanie aimerait une règle claire, mais n&#39;a pas décidé laquelle.</li><li>Mélanie voudrait une <strong>liste d&#39;attente</strong> pour les départs complets de la via ferrata, « comme au restaurant ».</li></ul><h3 id="la-decharge-de-responsabilite" tabindex="-1">La décharge de responsabilité <a class="header-anchor" href="#la-decharge-de-responsabilite" aria-label="Permalink to &quot;La décharge de responsabilité&quot;">​</a></h3><ul><li>Chaque participant doit signer une décharge. Pour un mineur, c&#39;est un parent. La décharge contient des questions sur la <strong>santé</strong> : problèmes cardiaques, épilepsie, allergies graves, capacité à nager.</li><li>Les décharges papier sont gardées dans des boîtes au sous-sol du chalet, « depuis 2014 ». Personne ne sait combien de temps il faut les garder.</li><li>Le texte de la décharge a été écrit par l&#39;avocat de l&#39;assurance. Il existe seulement en français.</li><li>Patrick : « Il faudrait que le guide puisse voir sur son téléphone, au quai, qui a signé et qui est allergique à quoi. »</li><li>Note : au quai et au départ de la via ferrata, <strong>le réseau cellulaire est très faible</strong>, parfois nul. Il y a du Wi-Fi seulement dans le chalet d&#39;accueil.</li></ul><h3 id="le-site-actuel-et-les-outils" tabindex="-1">Le site actuel et les outils <a class="header-anchor" href="#le-site-actuel-et-les-outils" aria-label="Permalink to &quot;Le site actuel et les outils&quot;">​</a></h3><ul><li>Site Wix créé en 2017 par le neveu de Patrick. Le <strong>compte Wix est à son nom</strong> et c&#39;est lui qui paie le forfait avec sa carte de crédit; Mélanie le rembourse chaque année.</li><li>Le nom de domaine <code>aventure-stmaurice.com</code> a été acheté par le neveu. Mélanie « pense » qu&#39;il est chez GoDaddy.</li><li>Les adresses courriel <code>@aventure-stmaurice.com</code> passent par <strong>Google Workspace</strong> (3 comptes : Mélanie, Patrick, info@).</li><li>Réseaux sociaux : une page Facebook (environ 8 000 abonnés), un compte Instagram, une fiche Google avec 1 100 avis (note moyenne de 4,7).</li><li>Patrick a <strong>environ 60 Go de vidéos</strong> 4K de drone et de caméra GoPro. Il voudrait une vidéo plein écran qui joue dès l&#39;ouverture de la page d&#39;accueil. « Comme les grosses stations de ski. »</li><li>Aucune statistique de visite. « Je ne sais pas si le site est visité. »</li></ul><h3 id="le-personnel-et-l-entretien" tabindex="-1">Le personnel et l&#39;entretien <a class="header-anchor" href="#le-personnel-et-l-entretien" aria-label="Permalink to &quot;Le personnel et l&#39;entretien&quot;">​</a></h3><ul><li>Mélanie veut pouvoir modifier elle-même les prix, les horaires et les textes. Elle est « correcte » avec Facebook et Excel, « pas plus ».</li><li>Mais l&#39;été, elle travaille 70 heures par semaine. « Si ça demande une heure par jour, ça ne marchera pas. »</li><li>Karine (l&#39;accueil) ne travaille que de mai à septembre. L&#39;hiver, il n&#39;y a que Mélanie et Patrick.</li><li>Les guides changent presque tous chaque année. Ce sont surtout des étudiants de 17 à 22 ans.</li><li>Mélanie : « Je ne veux pas dépendre d&#39;une seule personne comme avec le neveu. »</li></ul><h3 id="le-budget-et-les-delais" tabindex="-1">Le budget et les délais <a class="header-anchor" href="#le-budget-et-les-delais" aria-label="Permalink to &quot;Le budget et les délais&quot;">​</a></h3><ul><li>Budget annoncé : <strong>environ 8 000 $</strong> pour la construction. Mélanie n&#39;a pas pensé aux coûts annuels. « Le Wix nous coûte quoi, 300 $ par année? »</li><li>Une demande de <strong>subvention de 5 000 $</strong> a été faite à la MRC pour la « transformation numérique ». Réponse attendue en janvier. Si elle est acceptée, le budget monterait à 13 000 $.</li><li>Les deux kayaks adaptés achetés en 2024 l&#39;ont été grâce à un programme d&#39;aide qui exige que « les informations sur l&#39;offre adaptée soient accessibles à tous, y compris aux personnes ayant une incapacité ». Mélanie ne sait pas trop ce que ça implique pour le site.</li><li>Échéance ferme : <strong>ouverture des réservations le 1<sup>er</sup> mars 2027</strong>. Mélanie aimerait aussi vendre des cartes-cadeaux « pour Noël, cette année si possible ».</li><li>Les photos et les textes : « On a plein de photos, Patrick va vous envoyer ça. » Les textes en anglais : « On pourrait utiliser Google Traduction? »</li></ul><h3 id="en-vrac-a-la-fin-de-la-rencontre" tabindex="-1">En vrac, à la fin de la rencontre <a class="header-anchor" href="#en-vrac-a-la-fin-de-la-rencontre" aria-label="Permalink to &quot;En vrac, à la fin de la rencontre&quot;">​</a></h3><ul><li>Patrick : « Mon beau-frère dit qu&#39;il faudrait une <strong>application</strong>, comme ça les gens l&#39;ont sur leur téléphone. »</li><li>Mélanie : « Ce serait bien d&#39;afficher le <strong>niveau de la rivière</strong> et la météo en direct. »</li><li>Karine : « Les gens nous demandent tout le temps s&#39;il reste de la place pour le prêt-à-camper. Ils ne veulent pas appeler. »</li><li>Mélanie : « On pense peut-être ouvrir l&#39;hiver dans deux ou trois ans, avec de la raquette et du fatbike. »</li><li>Patrick : « Je ne veux pas que ça ait l&#39;air d&#39;un site de gros hôtel. On est une entreprise familiale. »</li></ul><h3 id="suivi" tabindex="-1">Suivi <a class="header-anchor" href="#suivi" aria-label="Permalink to &quot;Suivi&quot;">​</a></h3><ul><li>Mélanie doit retrouver les accès au nom de domaine et au compte Wix (communiquer avec le neveu).</li><li>Patrick doit envoyer une sélection de photos et de vidéos.</li><li>Studio Web FC doit produire un <strong>rapport de faisabilité technique</strong> en deux temps : d&#39;abord l&#39;<strong>évaluation technique</strong> (ce que le projet exige, ce qui le contraint, les risques et les technologies possibles), puis la <strong>proposition technique</strong> (les choix recommandés, les coûts et l&#39;échéancier).</li></ul></div><hr><h2 id="document-3-—-quelques-chiffres" tabindex="-1">Document 3 — Quelques chiffres <a class="header-anchor" href="#document-3-—-quelques-chiffres" aria-label="Permalink to &quot;Document 3 — Quelques chiffres&quot;">​</a></h2><p>Fournis par Mélanie après la rencontre, tirés de l&#39;Excel de l&#39;été 2026.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Donnée</th><th style="text-align:right;">Été 2026</th></tr></thead><tbody><tr><td style="text-align:left;">Clients (participants)</td><td style="text-align:right;">environ 9 000</td></tr><tr><td style="text-align:left;">Réservations (une réservation peut compter plusieurs participants)</td><td style="text-align:right;">environ 2 600</td></tr><tr><td style="text-align:left;">Réservations prises par téléphone</td><td style="text-align:right;">55 %</td></tr><tr><td style="text-align:left;">… par Messenger ou courriel</td><td style="text-align:right;">25 %</td></tr><tr><td style="text-align:left;">… par Viator</td><td style="text-align:right;">12 %</td></tr><tr><td style="text-align:left;">… sur place, sans réservation</td><td style="text-align:right;">8 %</td></tr><tr><td style="text-align:left;">Clients venant de l&#39;extérieur du Québec (Ontario, États-Unis, Europe)</td><td style="text-align:right;">environ 30 %</td></tr><tr><td style="text-align:left;">Journées où des départs ont été annulés à cause de la météo</td><td style="text-align:right;">11</td></tr><tr><td style="text-align:left;">Réservations de groupe (10 personnes et plus)</td><td style="text-align:right;">140</td></tr><tr><td style="text-align:left;">Participants mineurs</td><td style="text-align:right;">environ 25 %</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Comment lire ce mandat</p><p>Un client ne parle pas comme un analyste. Il mélange ce qu&#39;il <strong>veut</strong> (« une vidéo plein écran »), ce dont il a <strong>besoin</strong> (« que les gens réservent sans appeler ») et ce qu&#39;il <strong>suppose</strong> (« Google Traduction, ça devrait faire »). Votre travail, tout au long de la session, sera de faire le tri.</p></div>',17)])])}const m=t(i,[["render",s]]);export{g as __pageData,m as default};
